<div class="hero-strip"><span class="hero-strip-title">${t("Utaratibu. Mwelekeo. Mazungumzo.", "Order. Direction. Conversation.")}</span><span class="hero-strip-item" data-public-icon-trigger>${icon('link')}${t("Links zinachunguzwa", "Links checked")}</span><span class="hero-strip-item" data-public-icon-trigger>${icon('forward')}${t("Forwards zinadhibitiwa", "Forwards moderated")}</span><span class="hero-strip-item" data-public-icon-trigger>${icon('users')}${t("Admins wanaheshimiwa", "Admins respected")}</span></div>
